import{_ as e,o as t,c as r,a2 as _}from"./chunks/framework.Cms9CC3y.js";const o="/entislng/v5/assets/8dca734ac4405ca1-20261015000318-5wm0m8q.B6AEFBdq.png",u=JSON.parse('{"title":"数据库服务器连接正常，但数据库无法连接","description":"","frontmatter":{"title":"数据库服务器连接正常，但数据库无法连接","date":"2026-10-14T16:03:18.000Z","lastmod":"2026-11-24T18:39:53.000Z"},"headers":[],"relativePath":"guide/1165.md","filePath":"guide/帮助文档/管理维护说明/数据库的管理维护/数据库服务器连接正常，但数据库无法连接.md"}'),l={name:"guide/1165.md"};function i(n,a,s,c,d,E){return t(),r("div",null,[...a[0]||(a[0]=[_('<h1 id="数据库服务器连接正常-但数据库无法连接" tabindex="-1">数据库服务器连接正常，但数据库无法连接 <a class="header-anchor" href="#数据库服务器连接正常-但数据库无法连接" aria-label="Permalink to &quot;数据库服务器连接正常，但数据库无法连接&quot;">​</a></h1><hr><h3 id="_1-问题描述" tabindex="-1">1:问题描述 <a class="header-anchor" href="#_1-问题描述" aria-label="Permalink to &quot;1:问题描述&quot;">​</a></h3><ul><li>启动软件时，系统提示 &quot;数据库连接正常，但连接的数据库不存在&quot;，如下图：</li></ul><h3 id="_2-问题分析" tabindex="-1">2:问题分析 <a class="header-anchor" href="#_2-问题分析" aria-label="Permalink to &quot;2:问题分析&quot;">​</a></h3><ul><li>原因一（大部份情况）：数据库文件出现问题，如突然停电,权限损坏，硬盘坏道，病毒破坏等各种原因，像突然停电,权限损坏导致的一些轻微故障，可以通过下面的方法进行尝试修复，但如硬盘出现坏道等一些严重的故障原因，数据库文件无法简单修复，一般只能通过还原备份文件方式修复。</li><li>原因二：通过其他软件把附加的数据库名称修改掉，或链接的数据库文件被移动，如是这些原因导致的，则可以通过再次配置数据库连接来解决问题,操作方法，请参考<a href="http://softcool-publish.oss-cn-hongkong.aliyuncs.com/Documents/EntisMax/EntisMaxIV/Help/%E5%AE%89%E8%A3%85%E5%8D%B8%E8%BD%BD%E8%AF%B4%E6%98%8E/EntisMax%E8%BD%AF%E4%BB%B6%E5%AE%89%E8%A3%85/2-%E5%88%9D%E5%A7%8B%E5%8C%96%E8%AE%BE%E7%BD%AE%E5%90%91%E5%AF%BC.html" target="_blank" rel="noreferrer">《初始化设置向导》</a>中的数据库连接设定</li></ul><h3 id="_3-数据库轻微故障修复说明" tabindex="-1">3:数据库轻微故障修复说明 <a class="header-anchor" href="#_3-数据库轻微故障修复说明" aria-label="Permalink to &quot;3:数据库轻微故障修复说明&quot;">​</a></h3><p><img src="'+o+'" alt=""></p>',8)])])}const m=e(l,[["render",i]]);export{u as __pageData,m as default};
